mapper.select:
SELECT MAX(DT)
  FROM dws_product_info_d
 WHERE DT <= #{businessDate}

SELECT trade_serial_number AS tradeSerialNumber,
       product_code AS productCode,
       trader_name AS traderName,
       trade_date AS tradeDate,
       updated_at AS updatedAt
  FROM biz_semantic_trade_v
 WHERE authorized_user_id = #{ownerId}
   AND trade_serial_number = #{entityReference}
 ORDER BY trade_serial_number ASC
 LIMIT #{limit}
